CREATE TRIGGER DiscountsDelete  ON Discounts FOR DELETE AS DECLARE @MID      INT DECLARE @VSLastId INT SELECT  @MID=ID from Deleted SELECT @VSLastId=LastID from TablesID WHERE TablesID.TableName='Discounts' IF @MID > @VSLastId BEGIN  RETURN END  Insert Operations (OperationID, OperationType, OperationTable)  SELECT Deleted.ID, 'Delete' AS OperationType ,'Discounts' AS OperationTable From Deleted 